const match = (row, c) => String(row.source).toLowerCase()===c.source.toLowerCase() && row.problemId===c.problemId;
const xml = value => value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const candidates = value => value.current.techniques ?? [];
